codes.source:
key = "rl:{user_id}:{route}"
stored: { tokens: float, last_refill_ts: ms }

on request:
  now = nowMs()
  refill = (now - last_refill_ts) * rate_per_ms
  tokens = min(capacity, tokens + refill)
  if tokens >= 1:
      tokens -= 1; last_refill_ts = now; allow
  else:
      reject(429, Retry-After = (1 - tokens)/rate)
